{
  "components": [
    {
      "type": "claim",
      "quote": "Federal Postal Services Commission (PostCom) is a technically independent body responsible for supervising the Swiss postal market.",
      "gist": "PostCom is an independent body that supervises the Swiss postal market."
    },
    {
      "type": "claim",
      "quote": "It sees to it that basic postal services are efficient, of good quality and affordable to all.",
      "gist": "PostCom ensures postal services are efficient, high quality, and affordable."
    },
    {
      "type": "entity",
      "quote": "Rail Transport Commission (RailCom)",
      "gist": "RailCom is the Rail Transport Commission."
    },
    {
      "type": "claim",
      "quote": "The Rail Transport Commission (RailCom) is responsible for handling disputes regarding access to the railway network and the calculation of fees for the use of infrastructure.",
      "gist": "RailCom handles disputes about railway network access and infrastructure fees."
    },
    {
      "type": "claim",
      "quote": "In its supervisory capacity, RailCom monitors compliance with the principles of non-discrimination and transparency.",
      "gist": "RailCom monitors adherence to non-discrimination and transparency principles."
    }
  ]
}
